import { Router } from "express";
import { createSession, deleteSession, getSessionById, getSessions, updateSession, } from "../controllers/session.controller";
import { requiredAuth } from "../middleware/auth.middleware";
import { requireRole } from "../middleware/role.middleware";
const router = Router();
router.post("/", requiredAuth, requireRole("admin"), createSession);
router.get("/", requiredAuth, requireRole("admin"), getSessions);
router.get("/:id", requiredAuth, requireRole("admin"), getSessionById);
router.put("/:id", requiredAuth, requireRole("admin"), updateSession);
router.delete("/:id", requiredAuth, requireRole("admin"), deleteSession);
export default router;
